(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit22-market-examples-basic"]={"id":"unit22-market-examples-basic","unitId":"2-2","chapterIds":["2-2"],"unitType":"basic","group":"2-2단원 · 2. 새치기의 시장 논리","name":"어려운 소재 · 쉬운 예시 OX","level":"기본","desc":"새 예시로 개념을 이해하고 OX만 골라요.","revision":1,"originPage":"unit22","shuffleQuestions":true,"timedMode":"question","readingBlock":"market","readingChunk":"examples","parts":[{"name":"U22-E01 · 거래의 자유에도 조건이 있어요","items":[{"id":"U22-E01-B1","type":"ox","answer":"O","changed":"자유 지상주의자도 다른 관객의 권리를 해치는 거래는 허용하지 않는다. 민수와 지현이 동의해도 다른 관객의 자리를 빼앗을 수는 없다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"자유롭게 거래하려면 다른 사람의 권리를 해치지 않아야 해요. 표를 파는 민수와 사는 지현이 동의해도 다른 관객의 자리를 빼앗으면 안 돼요.","paragraphCount":2,"readingLabel":"4문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 4문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 4문단]\n줄 서기에 관해 시장을 옹호하는 입장에는 두 가지 주장이 있다. 하나는 개인의 자유 존중에 대한 것이고, 다른 하나는 행복이나 사회적 효용의 극대화에 대한 주장이다. 첫 번째는 자유 지상주의자의 입장이다. 그들은 타인의 권리를 침범하지 않는 한 원하는 재화는 무엇이든 자유롭게 사고팔 수 있어야 한다고 주장한다. 자유 지상주의자는 장기 매매 금지법에 반대하는 것과 같은 이유로 암표 매매 금지법에 반대한다. 이러한 법은 성인이 상호 동의에 따라 내린 선택을 방해함으로써 개인의 자유를 침해한다고 믿기 때문이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n민수는 자신이 가진 공연 표를 지현에게 팔려고 한다. 두 사람 모두 거래에 동의하지만, 다른 관객의 자리를 빼앗아 넘기는 일은 타인의 권리를 침해한다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["조건"],"evidence":{"title":"거래의 자유에도 조건이 있어요","statement":"자유 지상주의자도 다른 관객의 권리를 해치는 거래는 허용하지 않는다. 민수와 지현이 동의해도 다른 관객의 자리를 빼앗을 수는 없다.","explanation":"자유롭게 거래하려면 다른 사람의 권리를 해치지 않아야 해요. 표를 파는 민수와 사는 지현이 동의해도 다른 관객의 자리를 빼앗으면 안 돼요.","valid":["L04:4"],"sources":[{"id":"L04","title":"줄 서기를 돈으로 살 수 있을까","label":"4문단","sentences":[{"id":"L04:1","text":"줄 서기에 관해 시장을 옹호하는 입장에는 두 가지 주장이 있다.","paragraph":0,"memberIds":["L04:1"],"topic":"돈으로 줄을 사는 것(시장)에 찬성하는 쪽의 이유는 두 가지다."},{"id":"L04:2","text":"하나는 개인의 자유 존중에 대한 것이고, 다른 하나는 행복이나 사회적 효용의 극대화에 대한 주장이다.","paragraph":0,"memberIds":["L04:2"],"topic":"첫째는 '개인의 자유를 존중하자'는 것이다. 둘째는 '사람들의 만족(효용)을 가장 크게 만들자'는 것이다."},{"id":"L04:3","text":"첫 번째는 자유 지상주의자의 입장이다.","paragraph":0,"memberIds":["L04:3"],"topic":"첫째 이유는 '자유 지상주의자'의 생각이다. 개인의 자유를 무엇보다 중요하게 여기는 사람들이다."},{"id":"L04:4","text":"그들은 타인의 권리를 침범하지 않는 한 원하는 재화는 무엇이든 자유롭게 사고팔 수 있어야 한다고 주장한다.","paragraph":0,"memberIds":["L04:4"],"topic":"그들은 이렇게 말한다. \"남의 권리를 침범하지(피해를 주지) 않는 한, 무엇이든 자유롭게 사고팔 수 있어야 한다.\""},{"id":"L04:5","text":"자유 지상주의자는 장기 매매 금지법에 반대하는 것과 같은 이유로 암표 매매 금지법에 반대한다.","paragraph":0,"memberIds":["L04:5"],"topic":"그래서 그들은 '암표를 팔지 마라'는 법에 반대한다. '장기를 사고팔지 마라'는 법에 반대하는 것과 같은 이유에서다."},{"id":"L04:6","text":"이러한 법은 성인이 상호 동의에 따라 내린 선택을 방해함으로써 개인의 자유를 침해한다고 믿기 때문이다.","paragraph":0,"memberIds":["L04:6"],"topic":"어른 둘이 서로 좋다고 합의한 거래를 법이 막으면, 개인의 자유를 빼앗는 것이라고 믿기 때문이다."}]}]},"editorSourceVersion":"f5cccc7a3494401bc4b06c061dda3781de789c54c382e60ead97492a9d527f32"},{"id":"U22-E01-B2","type":"ox","answer":"X","changed":"민수와 지현이 동의했다면 다른 관객의 권리를 해쳐도 거래할 수 있다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"자유롭게 거래하려면 다른 사람의 권리를 해치지 않아야 해요. 표를 파는 민수와 사는 지현이 동의해도 다른 관객의 자리를 빼앗으면 안 돼요.","paragraphCount":2,"readingLabel":"4문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 4문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 4문단]\n줄 서기에 관해 시장을 옹호하는 입장에는 두 가지 주장이 있다. 하나는 개인의 자유 존중에 대한 것이고, 다른 하나는 행복이나 사회적 효용의 극대화에 대한 주장이다. 첫 번째는 자유 지상주의자의 입장이다. 그들은 타인의 권리를 침범하지 않는 한 원하는 재화는 무엇이든 자유롭게 사고팔 수 있어야 한다고 주장한다. 자유 지상주의자는 장기 매매 금지법에 반대하는 것과 같은 이유로 암표 매매 금지법에 반대한다. 이러한 법은 성인이 상호 동의에 따라 내린 선택을 방해함으로써 개인의 자유를 침해한다고 믿기 때문이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n민수는 자신이 가진 공연 표를 지현에게 팔려고 한다. 두 사람 모두 거래에 동의하지만, 다른 관객의 자리를 빼앗아 넘기는 일은 타인의 권리를 침해한다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["조건"],"evidence":{"title":"거래의 자유에도 조건이 있어요","statement":"민수와 지현이 동의해도 다른 관객의 권리를 해쳐서는 안 된다.","explanation":"자유롭게 거래하려면 다른 사람의 권리를 해치지 않아야 해요. 표를 파는 민수와 사는 지현이 동의해도 다른 관객의 자리를 빼앗으면 안 돼요.","valid":["L04:4"],"sources":[{"id":"L04","title":"줄 서기를 돈으로 살 수 있을까","label":"4문단","sentences":[{"id":"L04:1","text":"줄 서기에 관해 시장을 옹호하는 입장에는 두 가지 주장이 있다.","paragraph":0,"memberIds":["L04:1"],"topic":"돈으로 줄을 사는 것(시장)에 찬성하는 쪽의 이유는 두 가지다."},{"id":"L04:2","text":"하나는 개인의 자유 존중에 대한 것이고, 다른 하나는 행복이나 사회적 효용의 극대화에 대한 주장이다.","paragraph":0,"memberIds":["L04:2"],"topic":"첫째는 '개인의 자유를 존중하자'는 것이다. 둘째는 '사람들의 만족(효용)을 가장 크게 만들자'는 것이다."},{"id":"L04:3","text":"첫 번째는 자유 지상주의자의 입장이다.","paragraph":0,"memberIds":["L04:3"],"topic":"첫째 이유는 '자유 지상주의자'의 생각이다. 개인의 자유를 무엇보다 중요하게 여기는 사람들이다."},{"id":"L04:4","text":"그들은 타인의 권리를 침범하지 않는 한 원하는 재화는 무엇이든 자유롭게 사고팔 수 있어야 한다고 주장한다.","paragraph":0,"memberIds":["L04:4"],"topic":"그들은 이렇게 말한다. \"남의 권리를 침범하지(피해를 주지) 않는 한, 무엇이든 자유롭게 사고팔 수 있어야 한다.\""},{"id":"L04:5","text":"자유 지상주의자는 장기 매매 금지법에 반대하는 것과 같은 이유로 암표 매매 금지법에 반대한다.","paragraph":0,"memberIds":["L04:5"],"topic":"그래서 그들은 '암표를 팔지 마라'는 법에 반대한다. '장기를 사고팔지 마라'는 법에 반대하는 것과 같은 이유에서다."},{"id":"L04:6","text":"이러한 법은 성인이 상호 동의에 따라 내린 선택을 방해함으로써 개인의 자유를 침해한다고 믿기 때문이다.","paragraph":0,"memberIds":["L04:6"],"topic":"어른 둘이 서로 좋다고 합의한 거래를 법이 막으면, 개인의 자유를 빼앗는 것이라고 믿기 때문이다."}]}]},"claimEdits":[{"start":8,"end":14,"before":"동의했다면 ","after":"동의해도 "},{"start":25,"end":38,"before":"해쳐도 거래할 수 있다.","after":"해쳐서는 안 된다."}],"editorSourceVersion":"e51d588c419a9ee7d256394dbb475da5240883be7d19343238313288e969fdb2"}]},{"name":"U22-E02 · 거래에서 양쪽이 얻는 이익","items":[{"id":"U22-E02-B1","type":"ox","answer":"O","changed":"공리주의자는 손님과 가게 주인 모두 이익을 얻는다고 본다. 손님은 물건을 얻고, 주인은 돈을 벌어 더 행복해진다는 것이다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"손님은 필요한 물건을 얻어 만족하고, 가게 주인은 돈을 벌어 만족해요. 공리주의자는 이렇게 두 사람 모두 만족하면 행복도 늘어난다고 봐요.","paragraphCount":2,"readingLabel":"5문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 5문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 5문단]\n시장을 옹호하는 두 번째 주장은 경제학자에게 좀 더 친숙한 것으로 공리주의자의 입장이다. 공리주의자는 시장에서의 거래가 구매자와 판매자에게 똑같이 이익을 제공하고, 결과적으로 집단의 행복이나 사회적 효용을 향상한다고 말한다. 돈을 지불한 사람과 돈을 받고 대리로 줄을 선 사람 사이에 거래가 성립했다는 것은 결과적으로 양측이 모두 이익을 얻었다는 뜻이다. 125달러를 내고 대리로 줄을 서 주는 사람을 고용한 사람은 줄을 서지 않고 셰익스피어 연극을 관람함으로써 틀림없이 행복을 느낀다. 그렇지 않다면 애당초 사람을 고용하지 않았을 것이다. 몇 시간 동안 줄을 서서 125달러를 번 사람도 행복을 느낀다. 그렇지 않다면 애당초 그 일을 하지 않았을 것이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n손님은 필요한 물건을 사서 만족하고, 가게 주인은 물건을 팔아 수입을 얻어 만족한다. 두 사람은 각자 이익이 있다고 생각해 거래에 참여했다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["주체"],"evidence":{"title":"거래에서 양쪽이 얻는 이익","statement":"공리주의자는 손님과 가게 주인 모두 이익을 얻는다고 본다. 손님은 물건을 얻고, 주인은 돈을 벌어 더 행복해진다는 것이다.","explanation":"손님은 필요한 물건을 얻어 만족하고, 가게 주인은 돈을 벌어 만족해요. 공리주의자는 이렇게 두 사람 모두 만족하면 행복도 늘어난다고 봐요.","valid":["L05:2","L05:3"],"sources":[{"id":"L05","title":"줄 서기를 돈으로 살 수 있을까","label":"5문단","sentences":[{"id":"L05:1","text":"시장을 옹호하는 두 번째 주장은 경제학자에게 좀 더 친숙한 것으로 공리주의자의 입장이다.","paragraph":0,"memberIds":["L05:1"],"topic":"둘째 이유는 '공리주의자'의 생각이다. 경제학자들이 자주 쓰는 생각이다. 공리주의는 '사람들 행복의 합을 가장 크게 만들자'는 생각이다."},{"id":"L05:2","text":"공리주의자는 시장에서의 거래가 구매자와 판매자에게 똑같이 이익을 제공하고, 결과적으로 집단의 행복이나 사회적 효용을 향상한다고 말한다.","paragraph":0,"memberIds":["L05:2"],"topic":"공리주의자는 이렇게 말한다. \"거래를 하면 사는 사람도 이득이고 파는 사람도 이득이다. 그러니 사회 전체의 행복(효용)이 커진다.\""},{"id":"L05:3","text":"돈을 지불한 사람과 돈을 받고 대리로 줄을 선 사람 사이에 거래가 성립했다는 것은 결과적으로 양측이 모두 이익을 얻었다는 뜻이다.","paragraph":0,"memberIds":["L05:3"],"topic":"돈 낸 사람과 대신 줄 선 사람이 거래를 했다. 거래를 했다는 건 결과적으로 둘 다 이익을 얻었다는 뜻이다."},{"id":"L05:4","text":"125달러를 내고 대리로 줄을 서 주는 사람을 고용한 사람은 줄을 서지 않고 셰익스피어 연극을 관람함으로써 틀림없이 행복을 느낀다.","paragraph":0,"memberIds":["L05:4"],"topic":"125달러를 낸 사람은 줄을 안 서고도 연극을 본다. 그러니 분명히 행복하다."},{"id":"L05:5","text":"그렇지 않다면 애당초 사람을 고용하지 않았을 것이다.","paragraph":0,"memberIds":["L05:5"],"topic":"행복하지 않았다면 처음부터 돈을 내지 않았을 것이다."},{"id":"L05:6","text":"몇 시간 동안 줄을 서서 125달러를 번 사람도 행복을 느낀다.","paragraph":0,"memberIds":["L05:6"],"topic":"몇 시간 줄을 서고 125달러를 번 사람도 행복하다."},{"id":"L05:7","text":"그렇지 않다면 애당초 그 일을 하지 않았을 것이다.","paragraph":0,"memberIds":["L05:7"],"topic":"싫었으면 처음부터 그 일을 안 했을 것이다."}]}]},"editorSourceVersion":"68cc56f7b99b9eba386c7eb98768f98a6098d676d1e76fb34f9fb9ba729f5856"},{"id":"U22-E02-B2","type":"ox","answer":"X","changed":"이 거래에서 손님만 이익을 얻고 가게 주인은 언제나 손해를 본다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"손님은 필요한 물건을 얻어 만족하고, 가게 주인은 돈을 벌어 만족해요. 공리주의자는 이렇게 두 사람 모두 만족하면 행복도 늘어난다고 봐요.","paragraphCount":2,"readingLabel":"5문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 5문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 5문단]\n시장을 옹호하는 두 번째 주장은 경제학자에게 좀 더 친숙한 것으로 공리주의자의 입장이다. 공리주의자는 시장에서의 거래가 구매자와 판매자에게 똑같이 이익을 제공하고, 결과적으로 집단의 행복이나 사회적 효용을 향상한다고 말한다. 돈을 지불한 사람과 돈을 받고 대리로 줄을 선 사람 사이에 거래가 성립했다는 것은 결과적으로 양측이 모두 이익을 얻었다는 뜻이다. 125달러를 내고 대리로 줄을 서 주는 사람을 고용한 사람은 줄을 서지 않고 셰익스피어 연극을 관람함으로써 틀림없이 행복을 느낀다. 그렇지 않다면 애당초 사람을 고용하지 않았을 것이다. 몇 시간 동안 줄을 서서 125달러를 번 사람도 행복을 느낀다. 그렇지 않다면 애당초 그 일을 하지 않았을 것이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n손님은 필요한 물건을 사서 만족하고, 가게 주인은 물건을 팔아 수입을 얻어 만족한다. 두 사람은 각자 이익이 있다고 생각해 거래에 참여했다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["주체"],"evidence":{"title":"거래에서 양쪽이 얻는 이익","statement":"이 거래에서 손님과 가게 주인 모두 이익을 얻는다.","explanation":"손님은 필요한 물건을 얻어 만족하고, 가게 주인은 돈을 벌어 만족해요. 공리주의자는 이렇게 두 사람 모두 만족하면 행복도 늘어난다고 봐요.","valid":["L05:2","L05:3"],"sources":[{"id":"L05","title":"줄 서기를 돈으로 살 수 있을까","label":"5문단","sentences":[{"id":"L05:1","text":"시장을 옹호하는 두 번째 주장은 경제학자에게 좀 더 친숙한 것으로 공리주의자의 입장이다.","paragraph":0,"memberIds":["L05:1"],"topic":"둘째 이유는 '공리주의자'의 생각이다. 경제학자들이 자주 쓰는 생각이다. 공리주의는 '사람들 행복의 합을 가장 크게 만들자'는 생각이다."},{"id":"L05:2","text":"공리주의자는 시장에서의 거래가 구매자와 판매자에게 똑같이 이익을 제공하고, 결과적으로 집단의 행복이나 사회적 효용을 향상한다고 말한다.","paragraph":0,"memberIds":["L05:2"],"topic":"공리주의자는 이렇게 말한다. \"거래를 하면 사는 사람도 이득이고 파는 사람도 이득이다. 그러니 사회 전체의 행복(효용)이 커진다.\""},{"id":"L05:3","text":"돈을 지불한 사람과 돈을 받고 대리로 줄을 선 사람 사이에 거래가 성립했다는 것은 결과적으로 양측이 모두 이익을 얻었다는 뜻이다.","paragraph":0,"memberIds":["L05:3"],"topic":"돈 낸 사람과 대신 줄 선 사람이 거래를 했다. 거래를 했다는 건 결과적으로 둘 다 이익을 얻었다는 뜻이다."},{"id":"L05:4","text":"125달러를 내고 대리로 줄을 서 주는 사람을 고용한 사람은 줄을 서지 않고 셰익스피어 연극을 관람함으로써 틀림없이 행복을 느낀다.","paragraph":0,"memberIds":["L05:4"],"topic":"125달러를 낸 사람은 줄을 안 서고도 연극을 본다. 그러니 분명히 행복하다."},{"id":"L05:5","text":"그렇지 않다면 애당초 사람을 고용하지 않았을 것이다.","paragraph":0,"memberIds":["L05:5"],"topic":"행복하지 않았다면 처음부터 돈을 내지 않았을 것이다."},{"id":"L05:6","text":"몇 시간 동안 줄을 서서 125달러를 번 사람도 행복을 느낀다.","paragraph":0,"memberIds":["L05:6"],"topic":"몇 시간 줄을 서고 125달러를 번 사람도 행복하다."},{"id":"L05:7","text":"그렇지 않다면 애당초 그 일을 하지 않았을 것이다.","paragraph":0,"memberIds":["L05:7"],"topic":"싫었으면 처음부터 그 일을 안 했을 것이다."}]}]},"claimEdits":[{"start":7,"end":11,"before":"손님만 ","after":"손님과 가게 주인 모두 "},{"start":15,"end":36,"before":"얻고 가게 주인은 언제나 손해를 본다.","after":"얻는다."}],"editorSourceVersion":"c9f19fb2c7152fc1305c76d3ddc801d03ddd6ab8d030ef4726fdfdd9fc359dca"}]},{"name":"U22-E03 · 가치를 재는 시장의 기준","items":[{"id":"U22-E03-B1","type":"ox","answer":"O","changed":"시장을 지지하는 사람들은 다온이 책을 가장 소중히 여긴다고 본다. 세 사람 중 가장 많은 8천 원을 내겠다고 했기 때문이다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"시장을 지지하는 사람들은 돈을 얼마까지 내겠다는지로 책을 얼마나 원하는지 판단해요. 이 기준으로 보면 가장 많은 돈을 내겠다는 다온이 책을 가장 원한다고 보겠지요.","paragraphCount":2,"readingLabel":"6문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 6문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 6문단]\n이렇게 시장 거래의 결과로 구매자와 판매자는 모두 행복해지고 효용은 증가한다. 이것이 바로 자유 시장이 재화를 효율적으로 분배한다고 주장하는 경제학자들의 입장이다. 시장은 사람들이 상호 유리한 방향으로 거래하는 것을 허용함으로써, 재화에 가장 높은 가치를 매기는 사람에게 그 재화를 할당한다. 그리고 그 기준은 얼마나 지불할 의사가 있느냐로 측정한다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n같은 책 한 권을 원하는 세 사람이 있다. 가람은 2천 원, 나래는 5천 원, 다온은 8천 원까지 낼 의사가 있다고 말했다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["비교"],"evidence":{"title":"가치를 재는 시장의 기준","statement":"시장을 지지하는 사람들은 다온이 책을 가장 소중히 여긴다고 본다. 세 사람 중 가장 많은 8천 원을 내겠다고 했기 때문이다.","explanation":"시장을 지지하는 사람들은 돈을 얼마까지 내겠다는지로 책을 얼마나 원하는지 판단해요. 이 기준으로 보면 가장 많은 돈을 내겠다는 다온이 책을 가장 원한다고 보겠지요.","valid":["L06:3","L06:4"],"sources":[{"id":"L06","title":"줄 서기를 돈으로 살 수 있을까","label":"6문단","sentences":[{"id":"L06:1","text":"이렇게 시장 거래의 결과로 구매자와 판매자는 모두 행복해지고 효용은 증가한다.","paragraph":0,"memberIds":["L06:1"],"topic":"정리하면, 거래 덕분에 사는 사람도 파는 사람도 행복해지고 만족(효용)이 커진다."},{"id":"L06:2","text":"이것이 바로 자유 시장이 재화를 효율적으로 분배한다고 주장하는 경제학자들의 입장이다.","paragraph":0,"memberIds":["L06:2"],"topic":"그래서 경제학자들은 \"시장에 맡기면 물건(재화)이 낭비 없이 가장 알맞게(효율적으로) 나뉜다.\"라고 말한다."},{"id":"L06:3","text":"시장은 사람들이 상호 유리한 방향으로 거래하는 것을 허용함으로써, 재화에 가장 높은 가치를 매기는 사람에게 그 재화를 할당한다.","paragraph":0,"memberIds":["L06:3"],"topic":"시장에서는 서로 이득이 되는 거래를 자유롭게 할 수 있다. 그러면 물건은 그 물건을 가장 귀하게 여기는 사람에게 간다."},{"id":"L06:4","text":"그리고 그 기준은 얼마나 지불할 의사가 있느냐로 측정한다.","paragraph":0,"memberIds":["L06:4"],"topic":"그런데 '누가 가장 귀하게 여기는지'는 '누가 돈을 가장 많이 낼 마음이 있는지'로 잰다."}]}]},"editorSourceVersion":"19f661b87d510679e65c9dada94d305e2b53410a644ff920754a94156dd1d6d3"},{"id":"U22-E03-B2","type":"ox","answer":"X","changed":"시장을 지지하는 사람들은 2천 원을 내겠다는 가람이 책을 가장 소중히 여긴다고 본다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"시장을 지지하는 사람들은 돈을 얼마까지 내겠다는지로 책을 얼마나 원하는지 판단해요. 이 기준으로 보면 가장 많은 돈을 내겠다는 다온이 책을 가장 원한다고 보겠지요.","paragraphCount":2,"readingLabel":"6문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 6문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 6문단]\n이렇게 시장 거래의 결과로 구매자와 판매자는 모두 행복해지고 효용은 증가한다. 이것이 바로 자유 시장이 재화를 효율적으로 분배한다고 주장하는 경제학자들의 입장이다. 시장은 사람들이 상호 유리한 방향으로 거래하는 것을 허용함으로써, 재화에 가장 높은 가치를 매기는 사람에게 그 재화를 할당한다. 그리고 그 기준은 얼마나 지불할 의사가 있느냐로 측정한다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n같은 책 한 권을 원하는 세 사람이 있다. 가람은 2천 원, 나래는 5천 원, 다온은 8천 원까지 낼 의사가 있다고 말했다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["비교"],"evidence":{"title":"가치를 재는 시장의 기준","statement":"시장을 지지하는 사람들은 8천 원을 내겠다는 다온이 책을 가장 소중히 여긴다고 본다.","explanation":"시장을 지지하는 사람들은 돈을 얼마까지 내겠다는지로 책을 얼마나 원하는지 판단해요. 이 기준으로 보면 가장 많은 돈을 내겠다는 다온이 책을 가장 원한다고 보겠지요.","valid":["L06:3","L06:4"],"sources":[{"id":"L06","title":"줄 서기를 돈으로 살 수 있을까","label":"6문단","sentences":[{"id":"L06:1","text":"이렇게 시장 거래의 결과로 구매자와 판매자는 모두 행복해지고 효용은 증가한다.","paragraph":0,"memberIds":["L06:1"],"topic":"정리하면, 거래 덕분에 사는 사람도 파는 사람도 행복해지고 만족(효용)이 커진다."},{"id":"L06:2","text":"이것이 바로 자유 시장이 재화를 효율적으로 분배한다고 주장하는 경제학자들의 입장이다.","paragraph":0,"memberIds":["L06:2"],"topic":"그래서 경제학자들은 \"시장에 맡기면 물건(재화)이 낭비 없이 가장 알맞게(효율적으로) 나뉜다.\"라고 말한다."},{"id":"L06:3","text":"시장은 사람들이 상호 유리한 방향으로 거래하는 것을 허용함으로써, 재화에 가장 높은 가치를 매기는 사람에게 그 재화를 할당한다.","paragraph":0,"memberIds":["L06:3"],"topic":"시장에서는 서로 이득이 되는 거래를 자유롭게 할 수 있다. 그러면 물건은 그 물건을 가장 귀하게 여기는 사람에게 간다."},{"id":"L06:4","text":"그리고 그 기준은 얼마나 지불할 의사가 있느냐로 측정한다.","paragraph":0,"memberIds":["L06:4"],"topic":"그런데 '누가 가장 귀하게 여기는지'는 '누가 돈을 가장 많이 낼 마음이 있는지'로 잰다."}]}]},"claimEdits":[{"start":14,"end":17,"before":"2천 ","after":"8천 "},{"start":25,"end":29,"before":"가람이 ","after":"다온이 "}],"editorSourceVersion":"809acbc76771498e7e61b7017cf7290c2d6a11603c481ab8f86a1671fcaec494"}]},{"name":"U22-E04 · 암표 거래와 경제적 효율성","items":[{"id":"U22-E04-B1","type":"ox","answer":"O","changed":"맨큐는 지현이 표를 얻은 것을 효율적으로 나눈 사례라고 본다. 지현이 민수보다 높은 값을 내겠다고 했기 때문이다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"맨큐는 가장 비싼 값을 내겠다는 소비자가 표를 얻으면 효율적으로 나눈 것이라고 봐요. 지현은 민수보다 높은 값을 내겠다고 했어요.","paragraphCount":2,"readingLabel":"7문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 7문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 7문단]\n미국에서 가장 널리 쓰이는 경제학 교과서 중 한 권을 저술한 경제학자 그레고리 맨큐(Gregory Mankiw)는 암표 판매를 예로 들어 자유 시장의 미덕을 설명한다. 경제적 효율성이란 사회 구성원 전체의 경제적 행복을 극대화하는 방식으로 재화를 분배하는 것이다. 맨큐는 자유 시장이 얼마만큼의 돈을 지불할 의사가 있느냐를 기준으로 재화의 가치를 가장 높게 평가하는 구매자에게 재화를 공급함으로써 이러한 목적에 기여한다고 주장한다. 그는 암표 거래 현상을 예로 들면서 이렇게 말했다. “부족한 자원을 효율적으로 분배하려면, 재화는 그 가치를 가장 높게 평가하는 소비자에게 돌아가야 한다. 암표 거래가 바로 시장이 효율적 결론에 도달하는 방식을 나타내는 예다. …… 암표상은 표에 시장이 감당할 수 있는 최고 가격을 매김으로써, 가장 높은 가격을 지불할 의사가 있는 소비자가 실제로 표를 손에 넣을 수 있도록 보장한다.”\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n남은 입장권은 한 장이다. 민수는 1만 원, 지현은 2만 원을 낼 의사가 있다. 암표상은 시장에서 받을 수 있는 최고 가격인 2만 원에 지현에게 표를 팔았다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["주체"],"evidence":{"title":"암표 거래와 경제적 효율성","statement":"맨큐는 지현이 표를 얻은 것을 효율적으로 나눈 사례라고 본다. 지현이 민수보다 높은 값을 내겠다고 했기 때문이다.","explanation":"맨큐는 가장 비싼 값을 내겠다는 소비자가 표를 얻으면 효율적으로 나눈 것이라고 봐요. 지현은 민수보다 높은 값을 내겠다고 했어요.","valid":["L07:2","L07:3","L07:5"],"sources":[{"id":"L07","title":"줄 서기를 돈으로 살 수 있을까","label":"7문단","sentences":[{"id":"L07:1","text":"미국에서 가장 널리 쓰이는 경제학 교과서 중 한 권을 저술한 경제학자 그레고리 맨큐(Gregory Mankiw)는 암표 판매를 예로 들어 자유 시장의 미덕을 설명한다.","paragraph":0,"memberIds":["L07:1"],"topic":"맨큐는 미국에서 가장 널리 쓰이는 경제학 교과서 중 하나를 쓴 경제학자다. 그는 암표를 예로 들어 시장의 좋은 점(미덕)을 설명한다."},{"id":"L07:2","text":"경제적 효율성이란 사회 구성원 전체의 경제적 행복을 극대화하는 방식으로 재화를 분배하는 것이다.","paragraph":0,"memberIds":["L07:2"],"topic":"'경제적 효율성'이란 사회 모든 사람의 경제적 행복이 가장 커지도록 물건을 나누는 것이다."},{"id":"L07:3","text":"맨큐는 자유 시장이 얼마만큼의 돈을 지불할 의사가 있느냐를 기준으로 재화의 가치를 가장 높게 평가하는 구매자에게 재화를 공급함으로써 이러한 목적에 기여한다고 주장한다.","paragraph":0,"memberIds":["L07:3"],"topic":"시장은 '얼마 낼 마음이 있나'를 기준으로 삼는다. 그 기준으로 물건을 가장 귀하게 여기는 사람에게 준다. 그래서 시장은 모두의 행복을 키우는 데(효율성) 도움이 된다. 맨큐는 이렇게 주장한다."},{"id":"L07:4","text":"그는 암표 거래 현상을 예로 들면서 이렇게 말했다.","paragraph":0,"memberIds":["L07:4"],"topic":"그는 암표를 예로 들어 이렇게 말했다."},{"id":"L07:5","text":"“부족한 자원을 효율적으로 분배하려면, 재화는 그 가치를 가장 높게 평가하는 소비자에게 돌아가야 한다. 암표 거래가 바로 시장이 효율적 결론에 도달하는 방식을 나타내는 예다. …… 암표상은 표에 시장이 감당할 수 있는 최고 가격을 매김으로써, 가장 높은 가격을 지불할 의사가 있는 소비자가 실제로 표를 손에 넣을 수 있도록 보장한다.”","paragraph":0,"memberIds":["L07:5","L07:6","L07:7"],"topic":"\"물건이 모자랄 때 잘 나누려면, 그 물건을 가장 귀하게 여기는 사람이 가져야 한다."}]}]},"editorSourceVersion":"6c8cc7c4e1288d1a4cc8db38c555959c272a70490428e1920b52c61be469526a"},{"id":"U22-E04-B2","type":"ox","answer":"X","changed":"맨큐는 더 높은 값을 내겠다는 지현이 표를 얻었으므로 비효율적이라고 설명한다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"맨큐는 가장 비싼 값을 내겠다는 소비자가 표를 얻으면 효율적으로 나눈 것이라고 봐요. 지현은 민수보다 높은 값을 내겠다고 했어요.","paragraphCount":2,"readingLabel":"7문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 7문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 7문단]\n미국에서 가장 널리 쓰이는 경제학 교과서 중 한 권을 저술한 경제학자 그레고리 맨큐(Gregory Mankiw)는 암표 판매를 예로 들어 자유 시장의 미덕을 설명한다. 경제적 효율성이란 사회 구성원 전체의 경제적 행복을 극대화하는 방식으로 재화를 분배하는 것이다. 맨큐는 자유 시장이 얼마만큼의 돈을 지불할 의사가 있느냐를 기준으로 재화의 가치를 가장 높게 평가하는 구매자에게 재화를 공급함으로써 이러한 목적에 기여한다고 주장한다. 그는 암표 거래 현상을 예로 들면서 이렇게 말했다. “부족한 자원을 효율적으로 분배하려면, 재화는 그 가치를 가장 높게 평가하는 소비자에게 돌아가야 한다. 암표 거래가 바로 시장이 효율적 결론에 도달하는 방식을 나타내는 예다. …… 암표상은 표에 시장이 감당할 수 있는 최고 가격을 매김으로써, 가장 높은 가격을 지불할 의사가 있는 소비자가 실제로 표를 손에 넣을 수 있도록 보장한다.”\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n남은 입장권은 한 장이다. 민수는 1만 원, 지현은 2만 원을 낼 의사가 있다. 암표상은 시장에서 받을 수 있는 최고 가격인 2만 원에 지현에게 표를 팔았다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["주체"],"evidence":{"title":"암표 거래와 경제적 효율성","statement":"맨큐는 더 높은 값을 내겠다는 지현이 표를 얻었으므로 효율적이라고 설명한다.","explanation":"맨큐는 가장 비싼 값을 내겠다는 소비자가 표를 얻으면 효율적으로 나눈 것이라고 봐요. 지현은 민수보다 높은 값을 내겠다고 했어요.","valid":["L07:2","L07:3","L07:5"],"sources":[{"id":"L07","title":"줄 서기를 돈으로 살 수 있을까","label":"7문단","sentences":[{"id":"L07:1","text":"미국에서 가장 널리 쓰이는 경제학 교과서 중 한 권을 저술한 경제학자 그레고리 맨큐(Gregory Mankiw)는 암표 판매를 예로 들어 자유 시장의 미덕을 설명한다.","paragraph":0,"memberIds":["L07:1"],"topic":"맨큐는 미국에서 가장 널리 쓰이는 경제학 교과서 중 하나를 쓴 경제학자다. 그는 암표를 예로 들어 시장의 좋은 점(미덕)을 설명한다."},{"id":"L07:2","text":"경제적 효율성이란 사회 구성원 전체의 경제적 행복을 극대화하는 방식으로 재화를 분배하는 것이다.","paragraph":0,"memberIds":["L07:2"],"topic":"'경제적 효율성'이란 사회 모든 사람의 경제적 행복이 가장 커지도록 물건을 나누는 것이다."},{"id":"L07:3","text":"맨큐는 자유 시장이 얼마만큼의 돈을 지불할 의사가 있느냐를 기준으로 재화의 가치를 가장 높게 평가하는 구매자에게 재화를 공급함으로써 이러한 목적에 기여한다고 주장한다.","paragraph":0,"memberIds":["L07:3"],"topic":"시장은 '얼마 낼 마음이 있나'를 기준으로 삼는다. 그 기준으로 물건을 가장 귀하게 여기는 사람에게 준다. 그래서 시장은 모두의 행복을 키우는 데(효율성) 도움이 된다. 맨큐는 이렇게 주장한다."},{"id":"L07:4","text":"그는 암표 거래 현상을 예로 들면서 이렇게 말했다.","paragraph":0,"memberIds":["L07:4"],"topic":"그는 암표를 예로 들어 이렇게 말했다."},{"id":"L07:5","text":"“부족한 자원을 효율적으로 분배하려면, 재화는 그 가치를 가장 높게 평가하는 소비자에게 돌아가야 한다. 암표 거래가 바로 시장이 효율적 결론에 도달하는 방식을 나타내는 예다. …… 암표상은 표에 시장이 감당할 수 있는 최고 가격을 매김으로써, 가장 높은 가격을 지불할 의사가 있는 소비자가 실제로 표를 손에 넣을 수 있도록 보장한다.”","paragraph":0,"memberIds":["L07:5","L07:6","L07:7"],"topic":"\"물건이 모자랄 때 잘 나누려면, 그 물건을 가장 귀하게 여기는 사람이 가져야 한다."}]}]},"claimEdits":[{"start":30,"end":38,"before":"비효율적이라고 ","after":"효율적이라고 "}],"editorSourceVersion":"09527d96cb368a55a0c5357708ee49745a270938e57be0539e8a5620be7ba1fe"}]},{"name":"U22-E05 · 가정이 붙은 평가 읽기","items":[{"id":"U22-E05-B1","type":"ox","answer":"O","changed":"자유 시장을 지지하는 주장이 맞다고 가정하면, 암표상은 사회의 이익을 늘린 것이다. 8문단에서는 이 조건이 맞을 때 암표상을 칭찬해야 한다고 본다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"먼저 자유 시장을 지지하는 주장이 맞다는 조건을 붙였어요. 8문단은 그 조건이 맞을 때 암표상을 비난할 일이 아니라 칭찬할 일이라고 설명해요.","paragraphCount":2,"readingLabel":"8문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 8문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 8문단]\n자유 시장을 옹호하는 주장이 맞는다면, 줄 서기의 본질을 침범했다는 이유로 암표상과 대리 줄 서기를 비난해서는 안 된다. 오히려 가격이 낮게 책정된 재화를 가장 많은 대가를 지불하려는 사람에게 돌아가게 만들어 사회적 효용을 증가시킨 공로로 칭찬해야 마땅하다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n어떤 설명이 ‘자유 시장을 옹호하는 주장이 맞는다면’이라는 조건을 먼저 붙였다. 그 조건 아래에서, 암표상이 낮게 책정된 표를 더 많은 대가를 내겠다는 사람에게 보냈다고 가정한다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["조건"],"evidence":{"title":"가정이 붙은 평가 읽기","statement":"자유 시장을 지지하는 주장이 맞다고 가정하면, 암표상은 사회의 이익을 늘린 것이다. 8문단에서는 이 조건이 맞을 때 암표상을 칭찬해야 한다고 본다.","explanation":"먼저 자유 시장을 지지하는 주장이 맞다는 조건을 붙였어요. 8문단은 그 조건이 맞을 때 암표상을 비난할 일이 아니라 칭찬할 일이라고 설명해요.","valid":["L08:1","L08:2"],"sources":[{"id":"L08","title":"줄 서기를 돈으로 살 수 있을까","label":"8문단","sentences":[{"id":"L08:1","text":"자유 시장을 옹호하는 주장이 맞는다면, 줄 서기의 본질을 침범했다는 이유로 암표상과 대리 줄 서기를 비난해서는 안 된다.","paragraph":0,"memberIds":["L08:1"],"topic":"시장 편 주장이 맞다고 해 보자. 그러면 \"줄 서기를 망쳤다(줄 서기의 본질을 침범했다)\"며 암표상과 대리 줄 서기를 욕하면(비난하면) 안 된다."},{"id":"L08:2","text":"오히려 가격이 낮게 책정된 재화를 가장 많은 대가를 지불하려는 사람에게 돌아가게 만들어 사회적 효용을 증가시킨 공로로 칭찬해야 마땅하다.","paragraph":0,"memberIds":["L08:2"],"topic":"앞의 가정이 맞다면 오히려 칭찬해야 한다는 결론이 나온다. 가장 많은 돈을 내려는 사람에게 표를 보내 사회 전체의 만족을 키웠다는 이유다. 필자가 조건 없이 칭찬하는 말은 아니다."}]}]},"editorSourceVersion":"0277084d953a472e199c26ca86ee1fe3eb924e81508c110e1b9f6d890c32181b"},{"id":"U22-E05-B2","type":"ox","answer":"X","changed":"8문단에서는 자유 시장을 지지하는 주장이 맞아도 암표상을 칭찬하면 안 된다고 본다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","why":"먼저 자유 시장을 지지하는 주장이 맞다는 조건을 붙였어요. 8문단은 그 조건이 맞을 때 암표상을 비난할 일이 아니라 칭찬할 일이라고 설명해요.","paragraphCount":2,"readingLabel":"8문단 · 쉬운 예시","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 8문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 8문단]\n자유 시장을 옹호하는 주장이 맞는다면, 줄 서기의 본질을 침범했다는 이유로 암표상과 대리 줄 서기를 비난해서는 안 된다. 오히려 가격이 낮게 책정된 재화를 가장 많은 대가를 지불하려는 사람에게 돌아가게 만들어 사회적 효용을 증가시킨 공로로 칭찬해야 마땅하다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n어떤 설명이 ‘자유 시장을 옹호하는 주장이 맞는다면’이라는 조건을 먼저 붙였다. 그 조건 아래에서, 암표상이 낮게 책정된 표를 더 많은 대가를 내겠다는 사람에게 보냈다고 가정한다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","examplePractice":true,"skills":["조건"],"evidence":{"title":"가정이 붙은 평가 읽기","statement":"8문단에서는 자유 시장을 지지하는 주장이 맞다면 암표상을 칭찬해야 한다고 본다.","explanation":"먼저 자유 시장을 지지하는 주장이 맞다는 조건을 붙였어요. 8문단은 그 조건이 맞을 때 암표상을 비난할 일이 아니라 칭찬할 일이라고 설명해요.","valid":["L08:1","L08:2"],"sources":[{"id":"L08","title":"줄 서기를 돈으로 살 수 있을까","label":"8문단","sentences":[{"id":"L08:1","text":"자유 시장을 옹호하는 주장이 맞는다면, 줄 서기의 본질을 침범했다는 이유로 암표상과 대리 줄 서기를 비난해서는 안 된다.","paragraph":0,"memberIds":["L08:1"],"topic":"시장 편 주장이 맞다고 해 보자. 그러면 \"줄 서기를 망쳤다(줄 서기의 본질을 침범했다)\"며 암표상과 대리 줄 서기를 욕하면(비난하면) 안 된다."},{"id":"L08:2","text":"오히려 가격이 낮게 책정된 재화를 가장 많은 대가를 지불하려는 사람에게 돌아가게 만들어 사회적 효용을 증가시킨 공로로 칭찬해야 마땅하다.","paragraph":0,"memberIds":["L08:2"],"topic":"앞의 가정이 맞다면 오히려 칭찬해야 한다는 결론이 나온다. 가장 많은 돈을 내려는 사람에게 표를 보내 사회 전체의 만족을 키웠다는 이유다. 필자가 조건 없이 칭찬하는 말은 아니다."}]}]},"claimEdits":[{"start":23,"end":27,"before":"맞아도 ","after":"맞다면 "},{"start":32,"end":43,"before":"칭찬하면 안 된다고 ","after":"칭찬해야 한다고 "}],"editorSourceVersion":"95810d8127921d01503b5fc33484e051554a5397954516b5f4bb78eed8660b6a"}]}],"cat":"2-2단원"};})(window);
